/** Compute the distance between a point and the chord joining two points.
 * <p>The fraction returned by {@link Vector2D#chordFraction(Vector2D, Vector2D, Vector2D)
 * Vector2D.chordFraction(a, b, p)} is handed to {@link Vector2D#chordPoint(Vector2D,
 * Vector2D, double) Vector2D.chordPoint(a, b, fraction)}, and the Euclidean distance
 * between the point built there and {@code p} is returned.</p>
 * @param a first end of the chord
 * @param b second end of the chord
 * @param p point to check
 * @return distance between {@code p} and the point of the chord at the computed fraction
 */
public static double chordDistance(final Vector2D a, final Vector2D b, final Vector2D p) {
    final double fraction = Vector2D.chordFraction(a, b, p);
    return Vector2D.chordPoint(a, b, fraction).distance(p);
}

